def average_readings(readings):
    total = 0.0
    count = 0
    for x in readings:
        try:
            v = float(x)
        except (TypeError, ValueError) as e:
            raise ValueError from e
        total += v
        count += 1
    try:
        return total / count
    except ZeroDivisionError:
        return 0.0
